script:
(function () {
  'use strict';
  // Pay stub for one paycheck with a 457(b) deferral (tax year 2026).
  //   Federal taxable wages (W-2 box 1) = gross - 457(b) - 401(k)/403(b) - Section 125 deductions
  //   Social Security / Medicare wages   = gross - Section 125 deductions (457(b) deferrals stay in)
  //   Federal income tax: the 2026 annual liability on (box 1 wages x pay periods), spread evenly per
  //   paycheck, plus any extra withholding (an estimate, not the IRS Pub. 15-T percentage method).
  //   Social Security on this check stops once year-to-date wages reach the wage base; the 0.9%
  //   Additional Medicare applies to the part of year-to-date wages above $200,000.
  //   Net pay = gross - pre-tax deductions - taxes - after-tax deductions + reimbursements.
  // Checked in Node (fake DOM, whole script): $2,700 biweekly, single, 6% 457(b), $120 Section 125, 4% state:
  // box 1 wages $2,418, federal $5,364.16/yr (1,240 + 12% x 34,368) = $206.31/check, SS $159.96 (6.2% of
  // $2,580), Medicare $37.41, state $96.72, net $1,917.60. $10,000 check with $180,000 YTD: SS on $4,500 only
  // ($279.00); with $195,000 YTD: SS $0 and Medicare $145 + 0.9% x $5,000 = $190.00.
  // ---- 2026 FEDERAL PAYROLL CONSTANTS (tax year 2026) ----------------------------------
  // Copied from take-home-paycheck-calculator (verified there). Brackets and standard
  // deductions: IRS Rev. Proc. 2025-32 (as amended by P.L. 119-21). Child tax credit $2,200 and
  // $500 other-dependent credit: IRC 24(h) as amended by P.L. 119-21. Social Security wage base
  // and rate: SSA 2026 fact sheet. Medicare and 0.9% Additional Medicare: IRC 3101(b).
  var TAX_YEAR = 2026;
  var BRACKETS = { // upper limit of each band; rates 10, 12, 22, 24, 32, 35, 37%
    single: [12400, 50400, 105700, 201775, 256225, 640600],
    mfj:    [24800, 100800, 211400, 403550, 512450, 768700],
    mfs:    [12400, 50400, 105700, 201775, 256225, 384350],
    hoh:    [17700, 67450, 105700, 201750, 256200, 640600]
  };
  var RATES = [0.10, 0.12, 0.22, 0.24, 0.32, 0.35, 0.37];
  var STANDARD_DEDUCTION = { single: 16100, mfj: 32200, mfs: 16100, hoh: 24150 };
  var CHILD_CREDIT = 2200, OTHER_DEPENDENT_CREDIT = 500;
  var CREDIT_PHASEOUT_START = { single: 200000, hoh: 200000, mfs: 200000, mfj: 400000 }; // $50 per $1,000
  var SS_RATE = 0.062, SS_WAGE_BASE = 184500;
  var MEDICARE_RATE = 0.0145, ADDL_MEDICARE_RATE = 0.009, ADDL_MEDICARE_WITHHOLD_START = 200000;
  // ---------------------------------------------------------------------------------------

  function bracketTax(taxable, limits) {
    var tax = 0, lower = 0, marginal = 0;
    for (var i = 0; i < RATES.length; i++) {
      var upper = i < limits.length ? limits[i] : Infinity;
      if (taxable > lower) { tax += (Math.min(taxable, upper) - lower) * RATES[i]; marginal = RATES[i]; }
      lower = upper;
    }
    return { tax: tax, marginal: marginal };
  }

  // Annual paycheck model. o: gross, status, pretaxDefer (traditional plan deferral: exempt from
  // federal and flat state tax, still FICA wages), rothDefer (after-tax plan deferral), sec125
  // (health premiums etc.: exempt from federal, state and FICA), post (other after-tax deductions),
  // stateRate (%), kids, otherDeps, extraWH (extra federal withholding). All $ amounts are annual.
  function payroll(o) {
    var gross = o.gross, defer = o.pretaxDefer || 0, roth = o.rothDefer || 0;
    var sec125 = Math.min(o.sec125 || 0, Math.max(0, gross - defer));
    var ficaWages = Math.max(0, gross - sec125);
    var fedWages = Math.max(0, gross - defer - sec125);
    var taxable = Math.max(0, fedWages - STANDARD_DEDUCTION[o.status]);
    var bt = bracketTax(taxable, BRACKETS[o.status]);
    var credits = (o.kids || 0) * CHILD_CREDIT + (o.otherDeps || 0) * OTHER_DEPENDENT_CREDIT;
    credits = Math.max(0, credits - Math.ceil(Math.max(0, fedWages - CREDIT_PHASEOUT_START[o.status]) / 1000) * 50);
    var federal = Math.max(0, bt.tax - credits) + (o.extraWH || 0);
    var ss = SS_RATE * Math.min(ficaWages, SS_WAGE_BASE);
    var medicare = MEDICARE_RATE * ficaWages + ADDL_MEDICARE_RATE * Math.max(0, ficaWages - ADDL_MEDICARE_WITHHOLD_START);
    var state = (o.stateRate || 0) / 100 * fedWages;
    var post = o.post || 0;
    var net = gross - defer - roth - sec125 - federal - ss - medicare - state - post;
    return { gross: gross, defer: defer, roth: roth, sec125: sec125, ficaWages: ficaWages, fedWages: fedWages,
             taxable: taxable, federal: federal, marginal: bt.marginal, ss: ss, medicare: medicare, state: state,
             post: post, net: net, taxes: federal + ss + medicare + state };
  }
  // ---- 2026 457(b) LIMITS (IRS Notice 2025-67, tax year 2026) ----------------------------------
  var LIMITS = { basic457: 24500, catchUp50: 8000, catchUp60to63: 11250 }; // catch-ups: governmental plans only
  // ---------------------------------------------------------------------------------------
  function limit457(band, gov) { return LIMITS.basic457 + (gov ? (band === '60' ? LIMITS.catchUp60to63 : band === '50' ? LIMITS.catchUp50 : 0) : 0); }

  // o: gross, p (pay periods), status, d457, d401, sec125, post, reimb, extra (all per paycheck),
  //    stateRate, kids, otherDeps, ytd (Social Security / Medicare wages paid earlier this year)
  function stub(o) {
    var p = o.p;
    var yr = payroll({ gross: o.gross * p, status: o.status, pretaxDefer: (o.d457 + o.d401) * p, sec125: o.sec125 * p,
                       post: o.post * p, stateRate: o.stateRate, kids: o.kids, otherDeps: o.otherDeps, extraWH: o.extra * p });
    var fica = Math.max(0, o.gross - o.sec125);
    var ss = SS_RATE * Math.min(fica, Math.max(0, SS_WAGE_BASE - o.ytd));
    var medicare = MEDICARE_RATE * fica + ADDL_MEDICARE_RATE *
                   (Math.max(0, o.ytd + fica - ADDL_MEDICARE_WITHHOLD_START) - Math.max(0, o.ytd - ADDL_MEDICARE_WITHHOLD_START));
    var fedWages = Math.max(0, o.gross - o.d457 - o.d401 - o.sec125);
    var federal = yr.federal / p, state = o.stateRate / 100 * fedWages;
    var taxes = federal + ss + medicare + state;
    var net = o.gross - o.d457 - o.d401 - o.sec125 - taxes - o.post + o.reimb;
    return { fedWages: fedWages, fica: fica, federal: federal, ss: ss, medicare: medicare, state: state,
             taxes: taxes, net: net, year: yr, marginal: yr.marginal };
  }
  var moneyFmt = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', maximumFractionDigits: 2, minimumFractionDigits: 2 });
  var wholeFmt = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', maximumFractionDigits: 0 });
  function money(x) { return moneyFmt.format(Math.abs(x) < 0.005 ? 0 : x); }
  function whole(x) { return wholeFmt.format(Math.abs(x) < 0.5 ? 0 : x); }
  function signed(x) { if (Math.abs(x) < 0.005) return money(0); return (x < 0 ? '−' : '+') + moneyFmt.format(Math.abs(x)); }
  function minus(x) { return Math.abs(x) < 0.005 ? money(0) : '−' + moneyFmt.format(Math.abs(x)); }
  function pctText(x) { return (Math.round(x * 10) / 10) + '%'; }
  function num(id) { var el = document.getElementById(id); if (!el) return NaN; var v = parseFloat(el.value); return isNaN(v) ? NaN : v; }
  function val(id) { var el = document.getElementById(id); return el ? el.value : ''; }
  function setText(id, text) { var el = document.getElementById(id); if (el) el.textContent = text; }
  // rows: arrays of cells; a cell is a string or {t: text, strong: bool}. The first cell is a row header.
  // A row given as {group: text, span: n} becomes a full-width group heading.
  function fillTable(id, rows) {
    var body = document.getElementById(id);
    if (!body) return;
    while (body.firstChild) body.removeChild(body.firstChild);
    rows.forEach(function (row) {
      var tr = document.createElement('tr');
      if (row.group) {
        var g = document.createElement('th');
        g.setAttribute('scope', 'colgroup'); g.colSpan = row.span; g.textContent = row.group;
        tr.appendChild(g); body.appendChild(tr); return;
      }
      row.forEach(function (c, i) {
        var el = document.createElement(i === 0 ? 'th' : 'td');
        if (i === 0) el.setAttribute('scope', 'row');
        var text = typeof c === 'object' ? c.t : c;
        if (typeof c === 'object' && c.strong) { var s = document.createElement('strong'); s.textContent = text; el.appendChild(s); }
        else el.textContent = text;
        tr.appendChild(el);
      });
      body.appendChild(tr);
    });
  }
  function showError(id, msg) { var e = document.getElementById(id); if (!e) return; e.hidden = !msg; e.textContent = msg || ''; }
  function showNote(id, notes) { var n = document.getElementById(id); if (!n) return; n.hidden = notes.length === 0; n.textContent = notes.join(' '); }
  function wire(formId, update) {
    document.addEventListener('DOMContentLoaded', function () {
      var form = document.getElementById(formId);
      if (!form) return;
      var run = function () { try { update(); } catch (err) { /* keep the page usable */ } };
      form.addEventListener('input', run);
      form.addEventListener('change', run);
      form.addEventListener('submit', function (e) { e.preventDefault(); });
      run();
    });
  }
  function update() {
    var o = {
      gross: num('pdGross'), p: parseInt(val('pdFreq'), 10), status: val('pdStatus'), stateRate: num('pdState'),
      sec125: num('pdHealth'), d401: num('pd401'), post: num('pdPost'), reimb: num('pdReimb'), extra: num('pdExtra'),
      kids: Math.round(num('pdKids')), otherDeps: Math.round(num('pdOtherDeps')), ytd: num('pdYtd')
    };
    var mode = val('pdMode'), amt = num('pd457'), band = val('pdAge'), gov = val('pdEmployer') !== 'nongov';
    if (!BRACKETS[o.status]) o.status = 'single';
    if (!(o.p > 0)) o.p = 26;
    var all = [o.gross, o.stateRate, o.sec125, o.d401, o.post, o.reimb, o.extra, o.kids, o.otherDeps, o.ytd, amt];
    if (all.some(function (v) { return !isFinite(v) || v < 0; }) || o.gross > 1e7 || o.stateRate > 20 ||
        o.kids > 20 || o.otherDeps > 20 || (mode === 'pct' && amt > 100)) {
      showError('pdError', 'Enter gross pay, non-negative amounts, a 457(b) rate from 0 to 100% and a state rate from 0 to 20%.');
      return;
    }
    o.d457 = mode === 'pct' ? o.gross * amt / 100 : amt;
    if (o.d457 + o.d401 + o.sec125 + o.post > o.gross) {
      showError('pdError', 'Your deductions add up to more than your gross pay for this paycheck.');
      return;
    }
    showError('pdError', '');

    var s = stub(o), base = stub(Object.assign({}, o, { d457: 0 })), p = o.p;
    setText('pdNet', money(s.net));
    setText('pd457Out', money(o.d457));
    setText('pdTaxes', money(s.taxes));
    setText('pdBox1', money(s.fedWages));
    setText('pdBox3', money(s.fica));
    setText('pdNetNo457', money(base.net));
    setText('pdCost', money(base.net - s.net));
    setText('pdTaxSaved', money((base.federal + base.state) - (s.federal + s.state)));
    setText('pdMarginal', Math.round(s.marginal * 100) + '%');
    setText('pd457Year', whole(o.d457 * p));

    var y = s.year;
    var g = function (t) { return { group: t, span: 3 }; };
    fillTable('pdStub', [
      g('Earnings'),
      ['Gross pay', money(o.gross), money(o.gross * p)],
      g('Pre-tax deductions'),
      ['457(b) deferral', minus(o.d457), minus(o.d457 * p)],
      ['401(k) / 403(b) deferral', minus(o.d401), minus(o.d401 * p)],
      ['Health premiums and other Section 125', minus(o.sec125), minus(o.sec125 * p)],
      g('Taxes'),
      ['Federal income tax', minus(s.federal), minus(y.federal)],
      ['Social Security (6.2%)', minus(s.ss), minus(y.ss)],
      ['Medicare', minus(s.medicare), minus(y.medicare)],
      ['State and local income tax', minus(s.state), minus(y.state)],
      g('After-tax items'),
      ['After-tax deductions', minus(o.post), minus(o.post * p)],
      ['Reimbursements', money(o.reimb), money(o.reimb * p)],
      [{ t: 'Net pay', strong: true }, { t: money(s.net), strong: true }, { t: money(y.net + o.reimb * p), strong: true }]
    ]);

    var notes = [], lim = limit457(band, gov), yearly = o.d457 * p;
    if (yearly > lim + 0.005) {
      var checks = o.d457 > 0 ? Math.ceil(lim / o.d457) : 0;
      notes.push('At this rate your 457(b) deferrals would reach the ' + TAX_YEAR + ' limit of ' + whole(lim) + ' around paycheck ' + checks + ' of ' + p + '; your employer should stop the deduction there.');
    }
    if (o.ytd + s.fica > SS_WAGE_BASE && o.ytd < SS_WAGE_BASE) notes.push('This paycheck crosses the ' + whole(SS_WAGE_BASE) + ' Social Security wage base, so only part of it is taxed for Social Security.');
    if (o.ytd >= SS_WAGE_BASE) notes.push('You have already reached the ' + whole(SS_WAGE_BASE) + ' Social Security wage base this year, so no Social Security tax is withheld.');
    showNote('pdNote', notes);
  }

  wire('pdForm', update);
})();
